    id: "dsa-m5-49",
    number: "DSA-M5-49",
    title: "LRU cache structure",
    difficulty: "Easy",
    experienceLevel: "0–2 Years",
    category: "Linked Lists",
    expectedAnswer: "An LRU cache supports O(1) average get and put by combining a hash map for key lookup with a doubly linked list for recency order. The front represents most recently used; the back represents least recently used.",
    deepExplanation: "Step 1 — Data structures:\n- Map: key → node for O(1) average lookup.\n- Doubly linked list: O(1) remove and move-to-front.\n\nWITHOUT BUILT-IN / CORE:\n```ts\ninterface LruNode {\n  key: string;\n  value: number;\n  prev: LruNode | null;\n  next: LruNode | null;\n}\n\nclass LRUCache {\n  private readonly map = new Map<string, LruNode>();\n  private readonly head: LruNode = {\n    key: \"\",\n    value: 0,\n    prev: null,\n    next: null,\n  };\n  private readonly tail: LruNode = {\n    key: \"\",\n    value: 0,\n    prev: null,\n    next: null,\n  };\n\n  constructor(private readonly capacity: number) {\n    this.head.next = this.tail;\n    this.tail.prev = this.head;\n  }\n\n  private remove(node: LruNode): void {\n    node.prev!.next = node.next;\n    node.next!.prev = node.prev;\n  }\n\n  private insertAfterHead(node: LruNode): void {\n    node.next = this.head.next;\n    node.prev = this.head;\n    this.head.next!.prev = node;\n    this.head.next = node;\n  }\n\n  get(key: string): number | undefined {\n    const node = this.map.get(key);\n    if (!node) return undefined;\n\n    this.remove(node);\n    this.insertAfterHead(node);\n    return node.value;\n  }\n\n  put(key: string, value: number): void {\n    const existing = this.map.get(key);\n\n    if (existing) {\n      existing.value = value;\n      this.remove(existing);\n      this.insertAfterHead(existing);\n      return;\n    }\n\n    const node: LruNode = {\n      key,\n      value,\n      prev: null,\n      next: null,\n    };\n\n    this.map.set(key, node);\n    this.insertAfterHead(node);\n\n    if (this.map.size > this.capacity) {\n      const leastRecent = this.tail.prev!;\n\n      this.remove(leastRecent);\n      this.map.delete(leastRecent.key);\n    }\n  }\n}\n```\n\nWITH BUILT-IN-friendly Map-only approximation:\n```ts\nclass SimpleRecentCache {\n  private readonly cache = new Map<string, number>();\n\n  constructor(private readonly capacity: number) {}\n\n  get(key: string): number | undefined {\n    const value = this.cache.get(key);\n\n    if (value === undefined) return undefined;\n\n    this.cache.delete(key);\n    this.cache.set(key, value);\n\n    return value;\n  }\n\n  put(key: string, value: number): void {\n    this.cache.delete(key);\n    this.cache.set(key, value);\n\n    if (this.cache.size > this.capacity) {\n      const oldestKey = this.cache.keys().next().value as string | undefined;\n\n      if (oldestKey !== undefined) {\n        this.cache.delete(oldestKey);\n      }\n    }\n  }\n}\n```\n\nStep 2 — Example:\ncapacity=2\nput(A,1)\nput(B,2)\nget(A) → A becomes most recent\nput(C,3) → B is least recent → evict B.\n\nStep 3 — Complexity:\nGet and put are O(1) average.\nSpace is O(capacity).",
